#' Add outlier options and updated data to \code{seas} object 
#'
#' Add arguments from the \code{outlier} spec to a \code{seas} object.
#' This function uses the \code{static} function from the \code{seasonal} package; 
#' for more information on generating and evaluating a static seas object, 
#' see Section 8.1 of \insertCite{seasonal2018;textual}{sautilities}.
#'
#' Version 3.2, 2026-03-05
#'
#' @param seas_obj Object generated by \code{seas()} of the \code{seasonal} package
#'        \insertCite{seasonal2018}{sautilities}.
#'        This is a required entry.
#' @param new_data Time series object; updated data set from the data used to 
#'        generate \code{seas_obj}. This is a required entry.
#' @param outlier_span character string; sets the argument \code{outlier.span}.
#'        Default is \code{",")}.
#' @param outlier_types character string; sets the argument \code{outlier.types}.
#'        Default is \code{"ao,ls")}.
#' @param outlier_method Character string; sets the argument \code{outlier.method}.
#'        Default is \code{"addone")}.
#' @param outlier_critical Character string; sets the argument \code{outlier.critica}.
#'        Default is Ljung choice for number of observations in \code{new_data}.
#'        \insertCite{Ljung93}{sautilities}.
#' @param cv_alpha Numeric scalar; alpha for critical value.
#'        Default is \code{0.01}.
#' @return An updated static \code{seas} object with \code{outlier} arguments 
#'          included. For more information about arguments to the \code{outlier}
#'          spec, see Section 7.11 of \insertCite{Census2025;textual}{sautilities}.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' shoes_seas <- 
#'    seasonal::seas(shoes2007, 
#'       transform.function = "log",
#'       forecast.maxlead = 60, 
#'       x11 = "")
#' shoes_seas_outlier <- 
#'    static_with_outlier(shoes_seas, 
#'       new_data = shoes2008, 
#'       outlier_types = 'all',
#'       outlier_critical = 4.0)
#' @import stats
#' @importFrom Rdpack reprompt
#' @export
static_with_outlier <- 
   function(seas_obj = NULL, 
      new_data = NULL, 
      outlier_span = ",", 
      outlier_types = "ao,ls",
	  outlier_method = "addone",
	  outlier_critical = NULL,
	  cv_alpha = 0.01) {
    # Author: Brian C. Monsell (OEUS) Version 3.2, 2026-03-05
    
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        stop("must specify a seas object")
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
           stop("First argument must be a seas object")
        }
    }
    
    # check if a value is specified for \code{new_data}
    if (is.null(new_data)) {
        stop("must specify an updated data set")
    }
	
    # set value for \code{outlier_critical}, if necessary
	if (is.null(outlier_critical)) {
		outlier_critical <- 
		   set_critical_value(length(new_data), cv_alpha)
	}
    
    # save static version of \code{seas} object
    static_seas_object <- seasonal::static(seas_obj, evaluate = TRUE)
    
    # update static version of object with updated data, \code{outlier} arguments
    static_seas_object_outlier <- 
       update(static_seas_object, 
		  x = new_data, 
		  outlier.span = outlier_span, 
		  outlier.types = outlier_types, 
		  outlier.method = outlier_method,
		  outlier.critical = outlier_critical)
    
    # return static version of object
    return(static_seas_object_outlier)
}
